1	// What the desktop shell adds to a page, when there is one (docs/plan.md, step 4).
2	//
3	// The shell brings `window.preludeDesktop` on Prelude's own origin. Controls
4	// only the shell can drive are marked `data-desktop-only` and shown only when
5	// it is here; links it can do better are taken over - Pop out gets a real
6	// window, Open in browser the system's browser. In a browser none of this
7	// runs, and nothing is lost: the links work as links.
8	//
9	// This is the device's half: it relays between the page and the shell, and
10	// decides nothing. It is a script because it is genuinely imperative - a
11	// native dialog, a native window - which no binding or action expresses.
12	
13	const desktop = window.preludeDesktop ?? null;
14	
15	if (desktop) {
16	  document.querySelector('.prelude')?.setAttribute('data-desktop', '');
17	
18	  document.addEventListener('click', event => {
19	    const control = event.target.closest?.('[data-pick-folder], a[data-pop-out], a[target="_blank"]');
20	    if (!control || event.defaultPrevented || event.button !== 0) return;
21	    event.preventDefault();
22	    event.stopPropagation();
23	    run(control).catch(error => console.error('Prelude desktop:', error));
24	  }, true);
25	}
26	
27	async function run(control) {
28	  if (control.matches('[data-pick-folder]')) {
29	    const path = await desktop.pickFolder();
30	    if (!path) return;
31	    const form = control.closest('form');
32	    form.elements.path.value = path;
33	    form.requestSubmit();
34	    return;
35	  }
36	  const url = new URL(control.getAttribute('href'), location.href).href;
37	  if (control.matches('[data-pop-out]')) await desktop.popOut(url, control.getAttribute('target'));
38	  else await desktop.openInBrowser(url);
39	}
